SELECT
FROM users u LEFT JOIN departments d ON d.id = u.department_id
AND ( LOWER(u.username) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(u.real_name) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(u.email) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%') )
AND u.role = #{role}
AND u.status = #{status}
ORDER BY u.id DESC
